import * as React from 'react';
import type { RepoError } from '../../domain/shared';
import type { Clinician } from '../../domain/entities/clinician';
import type { EndorsedAnswer } from '../../domain/entities/endorsedAnswer';
import type { Patient } from '../../domain/entities/patient';
import type { PatientChatAnswer } from '../../domain/entities/patientChatAnswer';
import type { PatientQuestion } from '../../domain/entities/patientQuestion';
import type { DataNotice } from '../../application/view-models/notices';
import type {
  CareChatScreenViewModel,
  CareChatScreenViewModelAvailability,
  CareChatSubmitState,
  CareChatThreadEntry,
} from '../../application/view-models/care-chat.vm';
import { submitPatientQuestion } from '../../application/use-cases/submit-patient-question';
import { useIdentity, useRepositories } from '../app-context';
import { useAnswerDrafter } from '../answer-drafter-context';
import { CareChatView } from '../views/care-chat.view';
import { ScreenError, ScreenLoading } from '../screen-state';

/** Page size of `clinicians`: requested EXPLICITLY so the view knows how many rows
 *  of how many it sees. */
const CLINICIANS_PAGE_SIZE = 25;

/** Page size of `questions`: the patient's own thread, newest first. */
const QUESTIONS_PAGE_SIZE = 25;

/** Replies per question actually fetched (one draft is the norm). */
const ANSWERS_PER_QUESTION = 5;

/** The VIEW of this screen: `(props: <Screen>ViewModel) => JSX`. The view model
 *  travels spread as props. */
export type CareChatScreenView = (props: CareChatScreenViewModel) => React.ReactElement;

/** The view is INJECTED, not imported: it is a dependency of the container like its
 *  repositories. */
export interface CareChatScreenContainerProps {
  readonly view: CareChatScreenView;
}

const UNNORMALIZED: RepoError = {
  kind: 'transport',
  message: 'La consulta falló de una forma que el transporte no supo normalizar.',
  detail: 'promesa rechazada fuera del contrato `RepoResult`',
};

export function CareChatScreenContainer(
  props: CareChatScreenContainerProps,
): React.ReactElement {
  const View = props.view;
  const repositories = useRepositories();
  const drafter = useAnswerDrafter();
  const { identity, pending: identityPending } = useIdentity();
  const [principal, setPrincipal] = React.useState<Patient | null>(null);
  const [answers, setAnswers] = React.useState<readonly PatientChatAnswer[]>([]);
  const [answersNotice, setAnswersNotice] = React.useState<DataNotice | null>(null);
  const [clinicians, setClinicians] = React.useState<readonly Clinician[]>([]);
  const [cliniciansTotal, setCliniciansTotal] = React.useState(0);
  const [cliniciansPage, setCliniciansPage] = React.useState(0);
  const [cliniciansNotice, setCliniciansNotice] = React.useState<DataNotice | null>(null);
  const [library, setLibrary] = React.useState<readonly EndorsedAnswer[]>([]);
  const [libraryNotice, setLibraryNotice] = React.useState<DataNotice | null>(null);
  const [questions, setQuestions] = React.useState<readonly PatientQuestion[]>([]);
  const [questionsTotal, setQuestionsTotal] = React.useState(0);
  const [questionsPage, setQuestionsPage] = React.useState(0);
  const [questionsNotice, setQuestionsNotice] = React.useState<DataNotice | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [loadError, setLoadError] = React.useState<RepoError | null>(null);
  const [reloadToken, setReloadToken] = React.useState(0);
  const [submitState, setSubmitState] = React.useState<CareChatSubmitState>('idle');
  const [writeError, setWriteError] = React.useState<RepoError | null>(null);
  // "A load already SUCCEEDED" — not "first lap": a retry after a first failure must show the
  // spinner again, and a post-write reload must NOT blank the screen (L22).
  const hasLoadedRef = React.useRef(false);

  const reload = React.useCallback((): void => {
    setReloadToken((n) => n + 1);
  }, []);

  const email = identity?.email.trim().toLowerCase() ?? null;

  React.useEffect(() => {
    if (identityPending) return;
    let live = true;
    if (!hasLoadedRef.current) setLoading(true);
    setLoadError(null);
    const run = async (): Promise<void> => {
      // The patient filter has no `email` column, so the principal is resolved client-side.
      let patient: Patient | null = null;
      if (email !== null) {
        const patientsResult = await repositories.patient.listAll();
        if (!live) return;
        if (patientsResult.ok === false) {
          setLoadError(patientsResult.error);
          setLoading(false);
          return;
        }
        patient = patientsResult.data.items.find((p) => (p.email ?? '').trim().toLowerCase() === email) ?? null;
      }
      const [cliniciansResult, libraryResult, questionsResult] = await Promise.all([
        repositories.clinician.list({ first: CLINICIANS_PAGE_SIZE, skip: cliniciansPage * CLINICIANS_PAGE_SIZE }),
        repositories.endorsedAnswer.listAll(),
        patient === null
          ? null
          : repositories.patientQuestion.list({
              filter: { patientId: patient.id },
              sort: { field: 'askedAt', dir: 'DESC' },
              first: QUESTIONS_PAGE_SIZE,
              skip: questionsPage * QUESTIONS_PAGE_SIZE,
            }),
      ]);
      if (!live) return;
      if (cliniciansResult.ok === false) {
        setLoadError(cliniciansResult.error);
        setLoading(false);
        return;
      }
      setClinicians(cliniciansResult.data.items);
      setCliniciansTotal(cliniciansResult.data.total);
      setCliniciansNotice((cliniciansResult.data.unreadable ?? 0) > 0 ? { code: 'filas-ilegibles' } : null);
      if (libraryResult.ok === false) {
        setLoadError(libraryResult.error);
        setLoading(false);
        return;
      }
      if (libraryResult.data.hasMore === true) {
        setLibrary([]);
        setLibraryNotice({ code: 'agregado-truncado' });
      } else {
        setLibrary(libraryResult.data.items);
        setLibraryNotice((libraryResult.data.unreadable ?? 0) > 0 ? { code: 'filas-ilegibles' } : null);
      }
      if (questionsResult === null) {
        setQuestions([]);
        setQuestionsTotal(0);
        setQuestionsNotice({ code: 'sesion-no-identificada' });
        setAnswers([]);
        setAnswersNotice(null);
      } else {
        if (questionsResult.ok === false) {
          setLoadError(questionsResult.error);
          setLoading(false);
          return;
        }
        setQuestions(questionsResult.data.items);
        setQuestionsTotal(questionsResult.data.total);
        setQuestionsNotice((questionsResult.data.unreadable ?? 0) > 0 ? { code: 'filas-ilegibles' } : null);
        // Replies are read PER QUESTION: the patient's browser never receives another patient's thread.
        const answerPages = await Promise.all(
          questionsResult.data.items.map((q) =>
            repositories.patientChatAnswer.list({ filter: { questionId: q.id }, first: ANSWERS_PER_QUESTION }),
          ),
        );
        if (!live) return;
        const failed = answerPages.find((r) => r.ok === false);
        if (failed !== undefined && failed.ok === false) {
          setLoadError(failed.error);
          setLoading(false);
          return;
        }
        const rows: PatientChatAnswer[] = [];
        let unreadable = 0;
        for (const page of answerPages) {
          if (page.ok) {
            rows.push(...page.data.items);
            unreadable += page.data.unreadable ?? 0;
          }
        }
        setAnswers(rows);
        setAnswersNotice(unreadable > 0 ? { code: 'filas-ilegibles' } : null);
      }
      setPrincipal(patient);
      hasLoadedRef.current = true;
      setLoading(false);
    };
    void run().catch((cause: unknown) => {
      // EL DIAGNÓSTICO SOBREVIVE: la consola es el canal del INGENIERO; la pantalla, el del usuario.
      console.error('[archie] la consulta de esta pantalla falló fuera del contrato `RepoResult`:', cause);
      if (!live) return;
      setLoadError(UNNORMALIZED);
      setLoading(false);
    });
    return () => {
      live = false;
    };
  }, [repositories, reloadToken, cliniciansPage, questionsPage, email, identityPending]);

  const onAnswersPageChange = React.useCallback((page: number): void => {
    // Replies are fetched per question; there is no separate page of them.
    void page;
  }, []);

  const onCliniciansPageChange = React.useCallback((page: number): void => {
    setCliniciansPage(page);
  }, []);

  const onQuestionsPageChange = React.useCallback((page: number): void => {
    setQuestionsPage(page);
  }, []);

  const onCreatePatientQuestion = React.useCallback(
    (input: { readonly questionText: string }): void => {
      if (principal === null) return;
      setWriteError(null);
      setSubmitState('submitting');
      void submitPatientQuestion(
        {
          questions: repositories.patientQuestion,
          answers: repositories.patientChatAnswer,
          policyPacks: repositories.policyPack,
          library: repositories.endorsedAnswer,
          orgUnits: repositories.orgUnit,
          drafter,
        },
        {
          patientId: principal.id,
          questionText: input.questionText,
          careTeamId: principal.careTeamId,
          institutionHints: [principal.careTeam?.name],
        },
      )
        .then((result) => {
          if (result.ok === false) {
            setWriteError(result.error);
            setSubmitState('failed');
            return;
          }
          if (result.data.draftError !== null) {
            console.warn('[care-chat] the question was stored but no draft could be prepared:', result.data.draftError);
          }
          setSubmitState(result.data.answer === null ? 'sent-without-draft' : 'sent');
          setQuestionsPage(0);
          reload();
        })
        .catch((cause: unknown) => {
          console.error('[archie] la escritura falló fuera del contrato `RepoResult`:', cause);
          setWriteError({ ...UNNORMALIZED, message: 'La escritura falló de una forma que el transporte no supo normalizar.' });
          setSubmitState('failed');
        });
    },
    [repositories, drafter, principal, reload],
  );

  // Only ENDORSED replies reach the thread: an AI draft awaiting review is not patient-visible.
  const thread = React.useMemo(
    (): readonly CareChatThreadEntry[] =>
      questions.map((question) => {
        const reply = answers.find((a) => a.questionId === question.id && a.status === 'ENDORSED') ?? null;
        const reviewer = reply === null ? undefined : clinicians.find((c) => c.id === reply.reviewedById);
        return { question, reply, reviewerName: reviewer?.fullName ?? null };
      }),
    [questions, answers, clinicians],
  );

  const availability: CareChatScreenViewModelAvailability = {
    onCreatePatientQuestion:
      principal !== null ? { available: true } : { available: false, reason: 'sesion-no-identificada' },
  };

  const vm: CareChatScreenViewModel = {
    answers,
    answersNotice,
    answersTotal: answers.length,
    answersPage: 0,
    answersPageSize: ANSWERS_PER_QUESTION,
    onAnswersPageChange,
    clinicians,
    cliniciansNotice,
    cliniciansTotal,
    cliniciansPage,
    cliniciansPageSize: CLINICIANS_PAGE_SIZE,
    onCliniciansPageChange,
    library,
    libraryNotice,
    questions,
    questionsNotice,
    questionsTotal,
    questionsPage,
    questionsPageSize: QUESTIONS_PAGE_SIZE,
    onQuestionsPageChange,
    flaggedCount: null,
    libraryMatchCount: null,
    libraryTotalCount: null,
    loading,
    error: loadError,
    principal,
    thread,
    onCreatePatientQuestion,
    submitState,
    writeError,
    availability,
  };

  // ONE `return`, the conditional INSIDE a fragment — never an early return (ARCH-956).
  return (
    <>
      {loading ? (
        <ScreenLoading />
      ) : loadError !== null ? (
        <ScreenError error={loadError} onRetry={reload} />
      ) : (
        <View {...vm} />
      )}
    </>
  );
}

// THE ROUTE MODULE. `routes.config.tsx` lazy-imports this file and needs a prop-less
// `export default`: it binds the container to its view and does nothing else.
export default function CareChatScreenRoute(): React.ReactElement {
  return <CareChatScreenContainer view={CareChatView} />;
}
